"use strict";
const $=id=>document.getElementById(id),t=OrionI18n.t;
const journeys=[[2,5,8],[3,6,9],[4,7,10],[8,3,6],[9,4,7],[10,2,5]];
let variant=OrionProgress.variant('echo'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,distance=1,solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){return journeys[v][s];}
function echoTime(n){return 2*(17*n)/340;}
function setDistance(n){if(solved||!Number.isInteger(n)||n<1||n>10)return;distance=n;state='ready';render();}
function resetTrial(){distance=1;solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('echo')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;if(distance!==challenge())state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('resonance');}render();if(solved&&stage<2)$('next').focus();}
function drawing(){const x=65+distance*23;return `<svg viewBox="0 0 350 250" role="img" aria-label="${t(`Wall ${distance*17} metres from the horn. Sound path goes to the wall and back.`,`石壁距號角 ${distance*17} 米。聲音路徑到石壁再返回。`)}"><defs><marker id="arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="#e9c77f"/></marker></defs><path d="M35 80H${x-8}" stroke="#e9c77f" stroke-width="3" marker-end="url(#arrow)"/><path d="M${x-8} 140H35" stroke="#e9c77f" stroke-width="3" marker-end="url(#arrow)"/><rect x="${x}" y="45" width="20" height="125" rx="3" fill="#56747d" stroke="#b5c9c5"/><path d="M15 95H30L45 85V135L30 125H15Z" fill="#e4b66c"/>${state!=='ready'?`<circle class="pulse" cx="35" cy="80" r="7" style="--travel:${x-43}px"/>`:''}<g fill="#f4e9c4" font-size="16"><text x="175" y="30" text-anchor="middle">${t('Through air','經空氣傳播')}</text><text x="175" y="205" text-anchor="middle">${distance*17} m</text><text x="175" y="234" text-anchor="middle">${t('Outward →   ← Return','去程 →   ← 回程')}</text></g></svg>`;}
function hints(){const q=challenge();return[t('Try a nearby wall and a distant wall. Which echo takes longer to return?','試試近處和遠處的石壁。哪個回音較遲返回？'),t('The sound travels there AND back. Wall distance is half the whole sound journey.','聲音先去，再返回。石壁距離是聲音整段路程的一半。'),t(`For ${echoTime(q).toFixed(1)} seconds: 340 × ${echoTime(q).toFixed(1)} ÷ 2 = ${q*17} metres.`,`回音需 ${echoTime(q).toFixed(1)} 秒：340 × ${echoTime(q).toFixed(1)} ÷ 2 = ${q*17} 米。`)];}
function render(){const q=challenge(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Echo Cavern · Orion','回音洞窟 · Orion');$('stageTitle').textContent=t(`Chamber ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 個洞室 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Cave seals · ${p} / 3`,`洞穴封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);$('diagram').innerHTML=drawing();$('distance').value=distance;$('distance').disabled=solved;$('distanceValue').textContent=distance*17+' m';$('distance').setAttribute('aria-valuetext',t(`${distance*17} metres`,`${distance*17} 米`));
$('goal').textContent=t(`Recorded echo: ${echoTime(q).toFixed(1)} seconds. Find the wall distance that produces this return time.`,`記錄的回音：${echoTime(q).toFixed(1)} 秒。找出產生這個返回時間的石壁距離。`);$('reading').textContent=state==='ready'?t('Your echo time: send a pulse to measure.','你的回音時間：發出聲波來量度。'):t(`Your echo returns after ${echoTime(distance).toFixed(1)} seconds.`,`你的回音在 ${echoTime(distance).toFixed(1)} 秒後返回。`);$('reference').textContent=t('Model sound speed in air: 340 metres per second.','模型中的空氣聲速：每秒 340 米。');const messages={ready:['Move the wall and test your map.','移動石壁，測試你的地圖。'],wrong:[distance<q?'Echo too soon. Try a farther wall.':'Echo too late. Try a nearer wall.',distance<q?'回音太快返回。試試較遠的石壁。':'回音太遲返回。試試較近的石壁。'],success:['The echo matches. This cave map is restored!','回音吻合了，洞穴地圖修復成功！']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;
$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('resonance')?t('Resonance Sigil saved in your collection.','鳴響符印已存入收藏。'):'';}
$('distance').oninput=e=>setDistance(Number(e.target.value));
$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('echo',variant);observedVariant=OrionProgress.variant('echo');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('resonance');render();};function syncProgress(){const v=OrionProgress.variant('echo'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('resonance')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
